// Wi-Fi configuration adapted from lstux/Waveshare-C6-1.47 sd-server.
#include "config.h"
#include <Preferences.h>
static Preferences prefs; HpConfig hpConfig;
static String defaultApName(){uint64_t mac=ESP.getEfuseMac();char b[24];snprintf(b,sizeof(b),"HomePlanner-%04X",(unsigned)((mac>>32)&0xffff));return String(b);}
void hpConfigLoad(){prefs.begin("homeplanner",false);hpConfig.count=prefs.getUChar("netcount",0);if(hpConfig.count>HP_MAX_NETS)hpConfig.count=HP_MAX_NETS;for(uint8_t i=0;i<hpConfig.count;i++){String s="s"+String(i),p="p"+String(i);hpConfig.networks[i].ssid=prefs.getString(s.c_str(),"");hpConfig.networks[i].password=prefs.getString(p.c_str(),"");}hpConfig.apSsid=prefs.getString("apssid",defaultApName());hpConfig.apPassword=prefs.getString("appass","homeplan1");if(hpConfig.apPassword.length()<8)hpConfig.apPassword="homeplan1";hpConfig.hostname=prefs.getString("hostname","homeplanner");prefs.end();}
void hpConfigSave(){prefs.begin("homeplanner",false);prefs.putUChar("netcount",hpConfig.count);for(uint8_t i=0;i<HP_MAX_NETS;i++){String s="s"+String(i),p="p"+String(i);if(i<hpConfig.count){prefs.putString(s.c_str(),hpConfig.networks[i].ssid);prefs.putString(p.c_str(),hpConfig.networks[i].password);}else{prefs.remove(s.c_str());prefs.remove(p.c_str());}}prefs.putString("apssid",hpConfig.apSsid);prefs.putString("appass",hpConfig.apPassword);prefs.putString("hostname",hpConfig.hostname);prefs.end();}
void hpConfigClear(){prefs.begin("homeplanner",false);prefs.clear();prefs.end();hpConfig.count=0;}
void hpConfigAddNetwork(const String& ssid,const String& password){if(!ssid.length()||ssid.length()>32)return;int found=-1;for(uint8_t i=0;i<hpConfig.count;i++)if(hpConfig.networks[i].ssid==ssid){found=i;break;}if(found>=0){for(uint8_t i=found;i+1<hpConfig.count;i++)hpConfig.networks[i]=hpConfig.networks[i+1];hpConfig.count--;}if(hpConfig.count>=HP_MAX_NETS)hpConfig.count=HP_MAX_NETS-1;for(int i=hpConfig.count;i>0;i--)hpConfig.networks[i]=hpConfig.networks[i-1];hpConfig.networks[0]={ssid,password};hpConfig.count++;}
